package turbo.raid;
import java.nio.file.*;import com.google.gson.*;
public final class RaidSetupTests {
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("raid-setup-isolation-");String toa="{\"schema\":\"turbo-toa-setup-v1\",\"observedGear\":{\"MAGIC\":[123]},\"combatImplemented\":false}";String tob=toa.replace("turbo-toa","turbo-tob").replace("123","456");Path a=root.resolve("toa/instance-data.json"),b=root.resolve("tob/instance-data.json");try{RaidSetup.write(a,"toa",toa);RaidSetup.write(b,"tob",tob);if(!Files.readString(a).contains("123")||!Files.readString(b).contains("456"))throw new AssertionError("Separate raid persistence");boolean rejected=false;try{RaidSetup.validate("toa",tob);}catch(IllegalArgumentException e){rejected=true;}if(!rejected)throw new AssertionError("Cross-raid setup accepted");rejected=false;try{RaidSetup.validate("tob",tob.replace("false","true"));}catch(IllegalArgumentException e){rejected=true;}if(!rejected)throw new AssertionError("Unimplemented combat enabled");System.out.println("Raid setup checks passed: validated gear, separate save/load data, cross-raid rejection and no fake combat readiness. No game input.");}finally{Files.deleteIfExists(a);Files.deleteIfExists(b);Files.deleteIfExists(a.getParent());Files.deleteIfExists(b.getParent());Files.deleteIfExists(root);}}
}
